<?php
require_once __DIR__ . '/inc.php'; require_admin();
$pageTitle='Settings';$msg='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();
 $email=trim((string)($_POST['alert_email']??''));$from=trim((string)($_POST['mail_from']??''));$sev=(string)($_POST['alert_min_severity']??'medium');
 $window=max(10,min(3600,(int)($_POST['rate_limit_window_seconds']??60)));$limit=max(10,min(10000,(int)($_POST['rate_limit_requests']??120)));$cool=max(0,min(1440,(int)($_POST['alert_cooldown_minutes']??15)));
 $auto=isset($_POST['auto_block_rate_limit'])?'1':'0';$duration=max(5,min(10080,(int)($_POST['auto_block_duration_minutes']??30)));
 if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))$error='Alert email is invalid.';
 elseif($from!==''&&!filter_var($from,FILTER_VALIDATE_EMAIL))$error='From email is invalid.';
 elseif(!in_array($sev,['low','medium','high','critical'],true))$error='Invalid severity.';
 else{foreach(['alert_email'=>$email,'mail_from'=>$from,'alert_min_severity'=>$sev,'rate_limit_window_seconds'=>(string)$window,'rate_limit_requests'=>(string)$limit,'alert_cooldown_minutes'=>(string)$cool,'auto_block_rate_limit'=>$auto,'auto_block_duration_minutes'=>(string)$duration] as $k=>$v)set_setting($db,$k,$v);$msg='Settings saved.';}
}
$v=[];foreach(['alert_email','mail_from','alert_min_severity','rate_limit_window_seconds','rate_limit_requests','alert_cooldown_minutes','auto_block_rate_limit','auto_block_duration_minutes'] as $k)$v[$k]=get_setting($db,$k,'');
require __DIR__.'/header.php';?>
<h1>Settings</h1><p class="muted">Email uses PHP mail(). On WAMP, configure a mail relay or use your existing SMTP/Graph email service.</p><?php if($msg):?><p class="success"><?=h($msg)?></p><?php endif;?><?php if($error):?><p class="error"><?=h($error)?></p><?php endif;?>
<section class="panel"><form method="post"><input type="hidden" name="csrf_token" value="<?=h(csrf_token())?>"><div class="formrow">
<div class="field"><label>Alert recipient email</label><input type="email" name="alert_email" value="<?=h($v['alert_email'])?>" style="min-width:260px"></div><div class="field"><label>Sender email (optional)</label><input type="email" name="mail_from" value="<?=h($v['mail_from'])?>" style="min-width:260px"></div><div class="field"><label>Minimum alert severity</label><select name="alert_min_severity"><?php foreach(['low','medium','high','critical'] as $s):?><option value="<?=$s?>" <?=$v['alert_min_severity']===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select></div></div><hr style="border:0;border-top:1px solid #e5eaf1;margin:20px 0"><h2>Rate monitoring</h2><div class="formrow"><div class="field"><label>Window seconds</label><input type="number" name="rate_limit_window_seconds" min="10" max="3600" value="<?=h($v['rate_limit_window_seconds']?:'60')?>"></div><div class="field"><label>Requests per IP per window</label><input type="number" name="rate_limit_requests" min="10" max="10000" value="<?=h($v['rate_limit_requests']?:'120')?>"></div><div class="field"><label>Alert cooldown minutes per IP</label><input type="number" name="alert_cooldown_minutes" min="0" max="1440" value="<?=h($v['alert_cooldown_minutes']?:'15')?>"></div></div><hr style="border:0;border-top:1px solid #e5eaf1;margin:20px 0"><h2>Optional automatic blocking</h2><p class="muted">Off by default. Enable only after tuning the threshold and testing normal traffic. Auto-blocking can lock out legitimate users behind shared IPs.</p><label><input type="checkbox" name="auto_block_rate_limit" value="1" <?=$v['auto_block_rate_limit']==='1'?'checked':''?>> Automatically block an IP that exceeds the threshold</label><div class="field" style="margin-top:12px"><label>Automatic block duration in minutes</label><input type="number" name="auto_block_duration_minutes" min="5" max="10080" value="<?=h($v['auto_block_duration_minutes']?:'30')?>" style="max-width:220px"></div><p><button>Save settings</button></p></form></section>
<section class="panel"><h2>Recent email alert attempts</h2><table><thead><tr><th>Time</th><th>Event</th><th>Recipient</th><th>Status</th><th>Result</th></tr></thead><tbody><?php $logs=$db->query('SELECT * FROM alert_log ORDER BY id DESC LIMIT 20');while($r=$logs->fetch_assoc()):?><tr><td><?=h($r['created_at'])?></td><td><?=h((string)$r['event_id'])?></td><td><?=h($r['recipient'])?></td><td><?=h($r['status'])?></td><td><?=h($r['response_text'])?></td></tr><?php endwhile;?></tbody></table></section>
